  'use cache';

  cacheTag('products');

  const products = await getAllProducts();
  const generatedAt = new Date().toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });

  return (
    <section>
      <h2>Products</h2>
      <p>Cached at {generatedAt}. Use the refresh button to invalidate.</p>
      <ul>
        {products.map(product => (
          <li key={product.id}>
            {product.name} - ${product.price}
          </li>
        ))}
      </ul>
    </section>
  );
}

