  return (
    <div>
      <h1>Home</h1>
      <form
        action={async () => {
          'use server';
          revalidateTag('products');
        }}
      >
        <button type="submit">Refresh products cache</button>
      </form>
      <ProductsList />
    </div>
  );
}

